class DSU:
    def __init__(self, n):
        self.par = list(range(n))
        self.sz = [1] * n

    def find(self, x):
        while self.par[x] != x:
            self.par[x] = self.par[self.par[x]]
            x = self.par[x]
        return x

    def union(self, a, b):
        """返回 True 表示成功合并（原不连通）。"""
        a, b = self.find(a), self.find(b)
        if a == b:
            return False
        if self.sz[a] < self.sz[b]:
            a, b = b, a
        self.par[b] = a
        self.sz[a] += self.sz[b]
        return True


def kruskal(n, edges):
    """返回 MST 边权和；图不连通（无法形成生成树）返回 None。
    edges: (u, v, w) 列表，顶点 0..n-1。
    """
    edges = sorted(edges, key=lambda e: e[2])
    dsu = DSU(n)
    total = 0
    cnt = 0
    for u, v, w in edges:
        if dsu.union(u, v):
            total += w
            cnt += 1
            if cnt == n - 1:
                break
    return total if cnt == n - 1 else None


if __name__ == "__main__":
    # 经典图：答案由 1+2+2+5 组成
    edges = [(0, 1, 4), (0, 2, 1), (1, 2, 2), (1, 3, 5), (2, 3, 8), (2, 4, 10), (3, 4, 2)]
    assert kruskal(5, edges) == 10

    # 暴力交叉验证（小图穷举所有生成树）
    import itertools

    def brute_mst(n, edges):
        best = None
        for r in range(len(edges) + 1):
            for combo in itertools.combinations(edges, r):
                if len(combo) != n - 1:
                    continue
                dsu = DSU(n)
                ok = True
                cost = 0
                for u, v, w in combo:
                    if not dsu.union(u, v):
                        ok = False
                        break
                    cost += w
                if ok:
                    best = cost if best is None else min(best, cost)
        return best

    import random
    random.seed(0)
    for _ in range(30):
        n = random.randint(2, 6)
        es = []
        for u in range(n):
            for v in range(u + 1, n):
                if random.random() < 0.6:
                    es.append((u, v, random.randint(1, 20)))
        got = kruskal(n, es)
        expect = brute_mst(n, es)
        assert got == expect, (n, es, got, expect)

    # 不连通情形
    assert kruskal(3, [(0, 1, 1)]) is None
    # 单点
    assert kruskal(1, []) == 0

    print("All tests passed.")
